const fs = require('fs');
const path = require('path');

const genDir = path.join(__dirname, '../generators');
const part13 = JSON.parse(fs.readFileSync(path.join(genDir, 'pjok_part1_3.json'), 'utf8'));

const allQuestions = [...part13];
const seenQuestions = new Set(allQuestions.map(q => q.question));

function addQ(id, grade, topic, level, question, options, correctAnswer, explanation) {
  if (seenQuestions.has(question)) {
    throw new Error(`Duplicate question in PJOK: "${question}"`);
  }
  seenQuestions.add(question);
  allQuestions.push({
    id,
    grade,
    subject: "pjok",
    topic,
    level,
    question,
    options,
    correctAnswer,
    explanation
  });
}

console.log("Loaded Kelas 1-3 PJOK: " + allQuestions.length + " questions.");

