addQ("pjo-k4-u22", 4, "Analisis Kebutuhan Kebugaran Jasmani Fleksibilitas", "sulit", "Seorang atlet senam artistik dituntut memiliki fleksibilitas sendi yang tinggi. Fleksibilitas didefinisikan sebagai kemampuan tubuh untuk ...", ["Menggerakkan persendian melalui ruang gerak sendi (range of motion) secara maksimal tanpa mengalami cedera", "Mengangkat beban ratusan kilogram", "Berlari selama 5 jam tanpa henti", "Menahan napas di dalam air"], 0, "Fleksibilitas mengukur kelenturan rentang gerak artikulasi persendian.");
addQ("pjo-k4-u23", 4, "Latihan Sirkuit (Circuit Training)", "sulit", "Metode latihan kebugaran yang terdiri dari beberapa pos latihan berurutan (misal: Pos 1 push up, Pos 2 sit up, Pos 3 squat jump, Pos 4 lari zigzag) dinamakan ...", ["Circuit training (latihan sirkuit)", "Interval training", "Fartlek", "Latihan statis"], 0, "Circuit training melatih berbagai komponen kebugaran terpadu dalam stasiun pos.");
addQ("pjo-k4-u24", 4, "Bahaya Obesitas Dini pada Anak Usia Sekolah", "sulit", "Penumpukan lemak berlebih pada tubuh anak (obesitas) akibat terlalu banyak makan cepat saji (fast food) dan jarang berolahraga berisiko memicu penyakit jangka panjang berupa ...", ["Diabetes melitus tipe 2 dan penyakit jantung koroner sejak usia muda", "Penyakit anemia gizi", "Kerapuhan tulang rawan", "Pertumbuhan tinggi melesat"], 0, "Obesitas infantil memicu inflamasi vaskular dan resistensi reseptor insulin.");
addQ("pjo-k4-u25", 4, "Menjaga Sanitasi Handuk Mandi Pribadi", "sulit", "Handuk mandi basah harus dijemur membentang di bawah sinar matahari dan dicuci seminggu sekali karena handuk yang selalu lembap menjadi sarang ...", ["Bakteri Staphylococcus dan jamur penyebab jerawat punggung serta gatal", "Penyakit diabetes", "Kuman tetanus", "Penyakit patah tulang"], 0, "Serat handuk lembap merupakan habitat ideal kolonisasi mikroba patogen kulit.");
addQ("pjo-k4-u26", 4, "Etika Bertanding dalam Olahraga Bela Diri", "sulit", "Dalam pertandingan pencak silat, sasaran serangan yang SAH menghasilkan nilai angka adalah bagian ...", ["Togok tubuh (dada, perut, rusuk samping, dan punggung)", "Muka kepala dan leher", "Area kemaluan / selangkangan", "Tulang kering bawah"], 0, "Aturan IPSI melarang keras pukulan ke leher, wajah, dan kemaluan demi keselamatan atlet.");
addQ("pjo-k4-u27", 4, "Pencak Silat Sikap Pasang Terbuka vs Tertutup", "sulit", "Sikap pasang dalam pencak silat yang posisi tangannya tidak melindungi bagian tubuh secara langsung untuk memancing serangan lawan disebut sikap pasang ...", ["Terbuka", "Tertutup", "Kuda-kuda", "Sempurna"], 0, "Sikap pasang terbuka sengaja membuka celah semu guna memancing lawan menyerang.");
addQ("pjo-k4-u28", 4, "Dampak Penyakit DBD Terhadap Kadar Trombosit Darah", "sulit", "Penderita demam berdarah dengue (DBD) harus dirawat intensif di rumah sakit karena virus dengue menyebabkan penurunan drastis pada sel darah ...", ["Trombosit (keping darah) yang berisiko memicu pendarahan internal berbahaya", "Leukosit", "Eritrosit", "Hemoglobin"], 0, "Trombositopenia parah (< 100.000/uL) pada DBD meningkatkan risiko perdarahan syok dengue.");
addQ("pjo-k4-u29", 4, "Pencegahan DBD dengan Abatisasi", "sulit", "Menaburkan serbuk abate ke dalam bak penampungan air yang sulit dikuras secara rutin dinamakan abatisasi yang berfungsi untuk ...", ["Membunuh larva (jentik-jentik) nyamuk agar tidak menjadi nyamuk dewasa", "Mengubah air asin menjadi tawar", "Membuat air berbau harum", "Menjernihkan lumpur"], 0, "Larvasida temefos (abate) membasmi larva instar nyamuk penular DBD.");
addQ("pjo-k4-u30", 4, "Peran Wasit Sebagai Pengadil Tertinggi di Lapangan", "sulit", "Keputusan wasit utama dalam pertandingan sepak bola bersifat mutlak dan mengikat. Sikap yang harus dijunjung tinggi oleh kapten tim terhadap keputusan wasit adalah ...", ["Menghormati keputusan wasit dan menyampaikan klarifikasi secara santun melalui kapten", "Mengeroyok wasit bersama penonton", "Memukul peluit wasit", "Mogok bertanding dan membakar gawang"], 0, "Respect to referee adalah asas dasar fair play olahraga internasional.");

