addQ("pjo-k5-m01", 5, "Bola Basket Jumlah Pemain", "mudah", "Jumlah pemain inti dalam satu tim bola basket yang bertanding di lapangan adalah ... orang.", ["5 orang", "11 orang", "6 orang", "7 orang"], 0, "Bola basket dimainkan oleh 5 pemain di setiap regu.");
addQ("pjo-k5-m02", 5, "Tinggi Ring Bola Basket", "mudah", "Tinggi standar papan ring keranjang bola basket dari permukaan lantai adalah ... meter.", ["3,05 meter", "2,50 meter", "4,00 meter", "1,50 meter"], 0, "Tinggi ring basket standar FIBA adalah 3,05 meter (10 kaki).");
addQ("pjo-k5-m03", 5, "Nomor Lari Cepat (Sprint)", "mudah", "Lari jarak pendek (sprint) yang sering diperlombakan pada kejuaraan atletik sekolah dasar adalah lari jarak ...", ["60 meter dan 100 meter", "5.000 meter", "10.000 meter", "42 kilometer"], 0, "Lari jarak pendek mengutamakan kecepatan maksimal pada jarak 60m - 100m.");
addQ("pjo-k5-m04", 5, "Posisi Start Lari Jarak Pendek", "mudah", "Start yang digunakan oleh pelari pada perlombaan lari jarak pendek (sprint) adalah start ...", ["Jongkok (crouch start)", "Berdiri", "Melayang", "Duduk"], 0, "Lari sprint wajib menggunakan start jongkok dengan balok start (starting block).");
addQ("pjo-k5-m05", 5, "Start Lari Jarak Jauh", "mudah", "Start yang digunakan pada perlombaan lari jarak menengah dan jarak jauh adalah start ...", ["Berdiri (standing start)", "Jongkok", "Merayap", "Melompat"], 0, "Lari jarak menengah dan jauh menggunakan start berdiri.");
addQ("pjo-k5-m06", 5, "Asal Seni Bela Diri Pencak Silat", "mudah", "Seni bela diri tradisional pencak silat merupakan warisan budaya luhur yang berasal dari kepulauan ...", ["Indonesia (Nusantara)", "Jepang", "Tiongkok", "Korea"], 0, "Pencak silat adalah warisan budaya takbenda asli bangsa Indonesia.");
addQ("pjo-k5-m07", 5, "Induk Organisasi Pencak Silat Indonesia", "mudah", "Induk organisasi resmi olahraga pencak silat di seluruh wilayah Republik Indonesia adalah ...", ["IPSI (Ikatan Pencak Silat Indonesia)", "PSSI", "PBVSI", "PERBASI"], 0, "IPSI menaungi seluruh perguruan pencak silat nasional.");
addQ("pjo-k5-m08", 5, "Penyakit Menular Diare", "mudah", "Penyakit buang air besar cair berkali-kali akibat infeksi bakteri makanan kotor dinamakan ...", ["Diare", "Sakit maag", "Penyakit flu", "Kencing manis"], 0, "Diare ditandai defekasi feses cair akibat infeksi kuman usus.");
addQ("pjo-k5-m09", 5, "Penyakit Menular Influenza (Flu)", "mudah", "Penyakit saluran pernapasan menular yang disebabkan oleh virus dan ditandai demam, batuk, pilek, dan bersin adalah ...", ["Influenza (Flu)", "Sariawan", "Kutu air", "Terkilir"], 0, "Influenza adalah infeksi virus droplet menular pada saluran napas.");
addQ("pjo-k5-m10", 5, "Pengertian NAPZA", "mudah", "Kepanjangan dari singkatan istilah berbahaya NAPZA adalah ...", ["Narkotika, Psikotropika, dan Zat Adiktif", "Narkoba Alami Pembawa Zat Air", "Nutrisi Aman Penambah Zat Asam", "Negara Anti Pelanggaran Zat Asing"], 0, "NAPZA adalah Narkotika, Psikotropika, dan Zat Adiktif lainnya.");

addQ("pjo-k5-s01", 5, "Operan Atas Kepala Basket (Overhead Pass)", "sedang", "Operan bola basket yang dilakukan dari atas kepala dengan kedua tangan untuk meloloskan bola dari kawalan lawan yang tinggi dinamakan ...", ["Overhead pass", "Chest pass", "Bounce pass", "Underhand pass"], 0, "Overhead pass melepaskan bola dari atas kepala melampaui jangkauan lawan.");
addQ("pjo-k5-s02", 5, "Tembakan Melayang Basket (Lay-Up Shoot)", "sedang", "Tembakan memasukkan bola ke keranjang basket yang diawali dengan gerakan melangkah dua langkah lalu melompat dekat ring disebut ...", ["Lay-up shoot", "Jump shoot", "Free throw", "Slam dunk"], 0, "Lay-up shoot adalah teknik memasukkan bola melayang setelah 2 langkah langkah.");
addQ("pjo-k5-s03", 5, "Gerak Poros Putar Basket (Pivot)", "sedang", "Gerakan memutar badan dengan salah satu kaki tetap menempel di lantai sebagai poros putaran guna melindungi bola dari rebutan lawan disebut ...", ["Pivot", "Rebound", "Dribble", "Steal"], 0, "Pivot memutar badan dengan satu kaki tumpu sebagai poros tanpa melangkah.");
addQ("pjo-k5-s04", 5, "Aba-Aba Start Jongkok", "sedang", "Urutan aba-aba resmi pada perlombaan lari jarak pendek dengan start jongkok adalah ...", ["'Bersedia', 'Siap', 'Ya' (bunyi pistol)", "'Mulai', 'Jalan', 'Lari'", "'Satu', 'Dua', 'Tiga'", "'Awas', 'Cepat', 'Lompat'"], 0, "Aba-aba resmi atletik lari sprint: 'Bersedia', 'Siap', 'Ya' / tembakan pistol.");
addQ("pjo-k5-s05", 5, "Posisi Tubuh Aba-Aba Siap Start Jongkok", "sedang", "Pada saat mendengar aba-aba 'Siap' dalam start jongkok, posisi pinggul pelari harus ...", ["Diangkat lebih tinggi sedikit dari bahu dan pandangan ke arah depan garis", "Diturunkan menyentuh lantai", "Ditekuk ke bawah", "Tidur telentang"], 0, "Mengangkat pinggul memindahkan titik gravitasi ke depan siap meledak melesat.");
addQ("pjo-k5-s06", 5, "Empat Tahapan Lompat Jauh", "sedang", "Urutan tahapan teknik dalam cabang atletik lompat jauh yang benar adalah ...", ["Awalan lari -> Tolakan pada papan -> Melayang di udara -> Mendarat di bak pasir", "Tolakan -> Awalan -> Mendarat -> Melayang", "Mendarat -> Melayang -> Tolakan -> Awalan", "Melayang -> Awalan -> Mendarat -> Tolakan"], 0, "Lompat jauh terdiri dari: awalan lari, tolakan 1 kaki, fase melayang, dan mendarat 2 kaki.");
addQ("pjo-k5-s07", 5, "Mendarat Lompat Jauh di Bak Pasir", "sedang", "Saat mendarat di bak pasir lompat jauh, kedua kaki harus mendarat bersamaan dan badan dijatuhkan ke arah ...", ["Depan agar jarak lompatan tidak berkurang", "Belakang menyentuh punggung", "Samping kiri luar bak", "Terlentang"], 0, "Badan dicondongkan ke depan agar tidak mengurangi hasil pengukuran jejak pendaratan.");
addQ("pjo-k5-s08", 5, "Tolak Peluru Gaya Menyamping (Ortodoks)", "sedang", "Dalam cabang atletik tolak peluru, gerakan mendorong peluru besi dari pangkal leher menggunakan gaya menyamping arah tolakan disebut gaya ...", ["Ortodoks (menyamping)", "O'Brien (membelakangi)", "Gaya dada", "Gaya kangkang"], 0, "Gaya ortodoks memposisikan tubuh menyamping ke arah sasaran tolakan.");
addQ("pjo-k5-s09", 5, "Pencak Silat Pukulan Lurus", "sedang", "Pukulan dalam pencak silat dengan lintasan lurus ke arah dada lawan dengan bantuan putaran pinggang dinamakan pukulan ...", ["Lurus (depan)", "Bandul", "Sanggul", "Lingkar"], 0, "Pukulan lurus meluncur menuju ulu hati atau dada lawan.");
addQ("pjo-k5-s10", 5, "Pencak Silat Tendangan Lurus", "sedang", "Tendangan dalam pencak silat yang menyasar dada atau perut lawan dengan menggunakan ujung telapak kaki atau tumit lurus ke depan disebut tendangan ...", ["Lurus (depan)", "Sabit", "Tendangan T", "Tendangan belakang"], 0, "Tendangan lurus menghentakkan telapak kaki lurus ke target frontal.");
addQ("pjo-k5-s11", 5, "Pencak Silat Tendangan Sabit", "sedang", "Tendangan dengan lintasan melengkung seperti bentuk bulan sabit menyasar pinggang atau rusuk lawan disebut tendangan ...", ["Sabit (busur)", "Lurus", "Tendangan T", "Jeleg"], 0, "Tendangan sabit melingkar mengayun menyasar sisi samping tubuh lawan.");
addQ("pjo-k5-s12", 5, "Pencegahan Penyakit Menular Tifus (Tipes)", "sedang", "Penyakit demam tifoid (tifus) ditularkan melalui bakteri Salmonella pada makanan yang tidak bersih. Cara pencegahannya adalah ...", ["Memastikan makanan dan air minum dimasak hingga benar-benar matang higienis", "Minum air mentah dari selokan", "Membeli jajanan yang dikerubungi lalat", "Tidak pernah mencuci piring"], 0, "Memasak air mendidih dan menjaga higiene sanitasi membunuh bakteri Salmonella typhi.");
addQ("pjo-k5-s13", 5, "Penyakit Tidak Menular Diabetes Melitus", "sedang", "Penyakit tidak menular yang ditandai dengan kadar gula darah tinggi akibat kekurangan produksi hormon insulin dinamakan ...", ["Diabetes melitus (kencing manis)", "Influenza", "Cacar air", "Tifus"], 0, "Diabetes melitus terjadi karena disfungsi insulin pengatur glukosa darah.");
addQ("pjo-k5-s14", 5, "Penyakit Tidak Menular Hipertensi", "sedang", "Penyakit tekanan darah tinggi yang disebabkan oleh pola makan tinggi garam, kurang olahraga, dan stres disebut ...", ["Hipertensi", "Hipotensi", "Anemia", "Leukimia"], 0, "Hipertensi adalah tekanan darah persisten di atas ambang normal batas.");
addQ("pjo-k5-s15", 5, "Bahaya Narkotika Terhadap Otak", "sedang", "Penyalahgunaan zat narkotika sangat berbahaya karena merusak sel-sel saraf otak secara permanen yang mengakibatkan ...", ["Halusinasi, hilang akal sehat, ketergantungan kronis, dan kematian akibat overdosis", "Kecerdasan otak berlipat", "Kebugaran fisik abadi", "Penyembuhan semua penyakit"], 0, "Narkotika membajak sirkuit reward otak dan menyebabkan atrofi neuron saraf pusat.");
addQ("pjo-k5-s16", 5, "Zat Adiktif Minuman Keras Beralkohol", "sedang", "Minuman beralkohol tergolong ke dalam zat adiktif depresan karena zat alkohol di dalam tubuh akan ...", ["Menekan kerja sistem saraf pusat sehingga memperlambat refleks dan merusak kesadaran", "Mempercepat kerja otak", "Membuat mata sangat jeli", "Menaikkan kecerdasan"], 0, "Alkohol adalah depresan SSP yang melumpuhkan koordinasi motorik dan pertimbangan logis.");
addQ("pjo-k5-s17", 5, "Bahaya Zat Karbonil dan Tar Rokok Elektrik (Vape)", "sedang", "Rokok elektrik (vape) sama berbahayanya dengan rokok konvensional karena uap cairannya mengandung zat kimia ...", ["Nikotin beracun dan zat perasa kimia yang merusak jaringan paru-paru (EVALI)", "Vitamin herbal segar", "Madu alami lebah", "Air mineral murni"], 0, "Cairan aerosol vape mengandung nikotin pekat, formaldehida, dan partikel logam pemicu kerusakan paru.");
addQ("pjo-k5-s18", 5, "Pencegahan Bahaya Narkoba 'Katakan Tidak'", "sedang", "Prinsip utama generasi muda untuk membentengi diri dari jeratan narkotika adalah menerapkan prinsip ...", ["Katakan TIDAK pada Narkoba (Say No to Drugs) dan memilih lingkungan pergaulan yang positif", "Mencicipi sedikit demi pergaulan", "Menyimpan paket narkoba milik teman", "Berdiam diri melihat peredaran narkoba"], 0, "Ketegasan menolak sejak awal adalah perisai terkuat dari bahaya jeratan narkotika.");
addQ("pjo-k5-s19", 5, "Rebound dalam Permainan Bola Basket", "sedang", "Aktivitas melompat menangkap bola pantul yang gagal masuk ke ring basket disebut gerak ...", ["Rebound", "Dribble", "Pivot", "Passing"], 0, "Rebound merebut bola pantul tembakan yang meleset dari ring.");
addQ("pjo-k5-s20", 5, "Fungsi Papan Pantul (Backboard) Basket", "sedang", "Papan pantul di belakang ring basket berfungsi untuk ...", ["Memantulkan bola tembakan agar masuk ke dalam keranjang ring basket", "Menghalangi bola masuk", "Hiasan lapangan", "Tempat bersandar penonton"], 0, "Backboard memantulkan lintasan tembakan sudut ke dalam keranjang ring.");

addQ("pjo-k5-u01", 5, "Analisis Pelanggaran Traveling dalam Bola Basket", "sulit", "Dalam permainan bola basket, seorang pemain dinyatakan melakukan pelanggaran 'traveling' (walking) oleh wasit apabila pemain tersebut ...", ["Melangkahkan kaki lebih dari dua langkah sambil memegang bola tanpa melakukan dribble (memantulkan bola ke lantai)", "Memantulkan bola dengan satu tangan sambil berlari", "Mengoper bola setinggi dada", "Menembak bola ke ring"], 0, "Membawa bola melangkah lebih dari 2 langkah tanpa mendribble adalah traveling violation.");
addQ("pjo-k5-s02_b", 5, "Analisis Pelanggaran Double Dribble Basket", "sulit", "Pelanggaran 'double dribble' terjadi dalam bola basket apabila pemain ...", ["Menghentikan dribble lalu memegang bola dengan kedua tangan kemudian mendribble bola kembali", "Menggiring bola melintasi garis tengah", "Melakukan pivot satu kaki", "Melempar bola ke papan pantul"], 0, "Setelah bola dipegang dengan kedua tangan, pemain dilarang mendribble bola lagi.");
addQ("pjo-k5-u03", 5, "Biomekanika Dorongan Kaki pada Balok Start Jongkok", "sulit", "Saat aba-aba 'Ya' berbunyi, sudut tolakan kaki depan pada balok start yang paling efisien menghasilkan akselerasi horizontal ke depan adalah sudut ...", ["Sekitar 90 derajat pada kaki depan dan 120 derajat pada kaki belakang", "180 derajat lurus vertikal", "45 derajat terlentang", "Nol derajat rapat"], 0, "Fleksi sendi lutut 90-120 derajat memaksimalkan daya ledak otot kuadrisep mendorong tubuh ke depan.");
addQ("pjo-k5-u04", 5, "Transisi Lari Akselerasi ke Lari Maksimal Sprint", "sulit", "Pada fase awal 20 meter setelah start jongkok, posisi badan pelari sprint sebaiknya ...", ["Condong ke depan secara bertahap terangkat tegak seiring bertambahnya kecepatan lari", "Langsung tegak kaku sejak langkah pertama", "Menoleh ke belakang melihat lawan", "Membungkuk sampai menyentuh tanah"], 0, "Drive phase condong ke depan mengoptimalkan percepatan akselerasi sebelum fase kecepatan puncak.");
addQ("pjo-k5-u05", 5, "Analisis Gaya Melayang Jongkok pada Lompat Jauh", "sulit", "Pada lompat jauh gaya jongkok (tuck style), posisi kedua tungkai kaki saat melayang di udara adalah ...", ["Kedua lutut ditarik ditekuk merapat mendekati dada seperti posisi berjongkok", "Satu kaki lurus ke belakang dan satu kaki ke depan", "Kaki bergerak mengayuh seperti berjalan di udara", "Badan melenting membusur ke belakang"], 0, "Gaya jongkok melipat kedua tungkai ke arah dada untuk mempersiapkan ekstensi pendaratan.");
addQ("pjo-k5-u06", 5, "Faktor Penentu Jarak Lompatan pada Lompat Jauh", "sulit", "Dua faktor biomekanika utama yang paling menentukan jauhnya jarak lompatan atlet lompat jauh adalah ...", ["Kecepatan lari awalan maksimal dan kekuatan daya ledak kaki saat menolak di papan tumpuan", "Berat badan atlet yang sangat berat", "Tingginya bak pasir", "Panjangnya seragam olahraga"], 0, "Kecepatan horizontal awalan dikonversi menjadi momentum vertikal saat take-off.");
addQ("pjo-k5-u07", 5, "Analisis Sudut Rilis Optimal Tolak Peluru", "sulit", "Sudut elevasi pelepasan peluru besi dari pangkal leher yang menghasilkan jarak tolakan terjauh secara proyektil adalah sudut sekitar ...", ["40 sampai 42 derajat", "90 derajat tegak lurus ke atas", "15 derajat mendatar rendah", "75 derajat hampir vertikal"], 0, "Sudut pelepasan parabola proyektil ideal tolak peluru dengan tinggi rilis manusia berkisar 37-42 derajat.");
addQ("pjo-k5-u08", 5, "Kesalahan Melempar Tolak Peluru", "sulit", "Dalam tolak peluru, gerakan pelepasan peluru yang benar adalah DIDORONG (ditolak) dari pangkal leher. Jika peluru dilepaskan dengan cara DILEMPAR mengayun lengan dari belakang, maka hukumannya adalah ...", ["Diskualifikasi (lemparan tidak sah) karena membahayakan persendian bahu dan melanggar aturan", "Mendapat tambahan poin", "Diberi kesempatan mengulang sepuluh kali", "Dinyatakan sebagai pemenang"], 0, "Tolak peluru melarang gerak melempar yang berisiko dislokasi sendi bahu.");
addQ("pjo-k5-u09", 5, "Pencak Silat Tendangan T (Kekuatan Tumit)", "sulit", "Tendangan 'T' dalam pencak silat dilakukan dengan memutar tubuh menyamping dan menghentakkan hentakan telapak kaki atau tumit lurus ke samping. Keunggulan tendangan T adalah ...", ["Memiliki daya dorong sangat kuat untuk menjatuhkan lawan yang sedang menyerbu", "Sangat mudah ditangkap lawan", "Tidak memerlukan keseimbangan", "Hanya menyasar ujung kaki lawan"], 0, "Tendangan T memanfaatkan kekuatan otot panggul dan berat badan lateral mendobrak pertahanan.");
addQ("pjo-k5-u10", 5, "Pencak Silat Teknik Tangkapan dan Bantingan", "sulit", "Ketika lawan melakukan tendangan lurus, pesilat menangkap tungkai kaki lawan lalu menyapu kaki tumpu lawan hingga jatuh. Teknik kombinasi ini dinamakan ...", ["Tangkapan disusul bantingan / sapuan", "Kuda-kuda pasif", "Pukulan bandul", "Tangkisan atas"], 0, "Menangkap serangan kaki lawan disusul menggunting/menyapu kaki tumpu menghasilkan nilai jatuhan sah.");
addQ("pjo-k5-u11", 5, "Peran Imunisasi Dasar Lengkap pada Anak", "sulit", "Pemberian vaksin imunisasi dasar lengkap pada anak usia sekolah bertujuan untuk merangsang sistem kekebalan tubuh memproduksi ...", ["Antibodi spesifik yang mengingat dan melumpuhkan antigen patogen penyakit berbahaya", "Racun kimia di dalam darah", "Lemak jenuh di pembuluh darah", "Kadar gula darah"], 0, "Vaksin mengenalkan antigen jinak agar limfosit membentuk memori imunologi jangka panjang.");
addQ("pjo-k5-u12", 5, "Mekanisme Penularan Penyakit TBC (Tuberkulosis)", "sulit", "Bakteri Mycobacterium tuberculosis penular penyakit paru-paru TBC menyebar melalui udara (airborne) saat penderita ...", ["Batuk, bersin, atau berbicara tanpa menutup mulut dan droplet kuman terhirup orang sehat", "Berjabat tangan santai", "Meminjam buku perpustakaan", "Berenang di air kolam"], 0, "Aerosol droplet nuclei dari batuk penderita TBC aktif melayang di udara tertutup.");
addQ("pjo-k5-u13", 5, "Dampak Pola Hidup Sedentary Terhadap Penyakit Jantung", "sulit", "Kebiasaan duduk diam sepanjang hari tanpa berolahraga (gaya hidup sedentary) menyebabkan elastisitas pembuluh darah menurun dan penumpukan plak kolesterol yang memicu ...", ["Penyakit jantung koroner dan serangan jantung mendadak", "Penyakit patah kuku", "Kekuatan otot bertambah", "Penurunan berat badan drastis"], 0, "Inaktivitas fisik memicu disfungsi endotelium dan sindrom aterosklerosis pembuluh koroner.");
addQ("pjo-k5-u14", 5, "Bahaya Narkoba Golongan Stimulan (Sabu/Ekstasi)", "sulit", "Zat narkoba golongan stimulan memaksa jantung berdenyut sangat kencang dan merusak pembuluh darah otak. Bahaya fatal yang dapat terjadi adalah ...", ["Pecahnya pembuluh darah otak (stroke pendarahan) dan gagal jantung mendadak", "Kebutaan sementara", "Tidur pulas berminggu-minggu", "Gigi menjadi putih berkilau"], 0, "Stimulan memicu krisis hipertensi masif dan vasokonstriksi serebral letal.");
addQ("pjo-k5-u15", 5, "Bahaya Narkoba Golongan Depresan (Heroin/Putaw)", "sulit", "Zat narkotika golongan depresan opiat menekan pusat kendali pernapasan di batang otak. Kematian akibat overdosis heroin biasanya disebabkan oleh ...", ["Asfiksia (berhentinya pernapasan paru-paru secara total saat tertidur)", "Jantung berdetak terlalu kencang", "Kelebihan pasokan oksigen", "Suhu tubuh mendidih panas"], 0, "Overdosis opioid menekan kemoreseptor medula oblongata hingga henti napas komplit.");
addQ("pjo-k5-u16", 5, "Bahaya Zat Halusinogen (LSD / Jamur Magic Mushroom)", "sulit", "Zat halusinogen mengubah persepsi sensorik otak pemakainya sehingga mendengar atau melihat hal-hal yang tidak nyata. Bahaya terbesar bagi keselamatan jiwa adalah ...", ["Pemakai kehilangan kesadaran realitas hingga melakukan tindakan fatal bunuh diri atau mencelakai orang lain", "Meningkatkan daya hafal pelajaran", "Menyembuhkan demam", "Membuat tubuh kebal api"], 0, "Halusinasi ekstrem memicu delusi psikotik berbahaya tanpa kontrol kesadaran.");
addQ("pjo-k5-u17", 5, "Analisis Nilai Tembakan Tiga Angka (Three-Point Shoot) Basket", "sulit", "Tembakan bola basket yang dilepaskan pemain dari luar garis lengkung setengah lingkaran (three-point line) dan berhasil masuk ke ring menghasilkan nilai ...", ["3 poin", "2 poin", "1 poin", "4 poin"], 0, "Tembakan sukses dari luar garis perimeter 3-point bernilai 3 angka.");
addQ("pjo-k5-u18", 5, "Nilai Tembakan Hukuman Bebas (Free Throw) Basket", "sulit", "Tembakan lemparan bebas tanpa kawalan dari garis batas foul line setelah terjadi pelanggaran (free throw) bernilai ... per tembakan sukses.", ["1 poin", "2 poin", "3 poin", "0,5 poin"], 0, "Setiap bola tembakan bebas (free throw) yang masuk bernilai 1 poin.");
addQ("pjo-k5-u19", 5, "Pencegahan Terjadinya Heatstroke Saat Lari Siang Hari", "sulit", "Heatstroke (sengatan panas ekstrem) adalah kondisi darurat medis saat suhu tubuh melonjak di atas 40 derajat Celsius dan tubuh berhenti berkeringat. Gejala kritis yang harus segera ditolong adalah ...", ["Kulit panas kering memerah, korban linglung bingung, dan pingsan tak sadarkan diri", "Badan menggigil kedinginan", "Keringat keluar banjir", "Gigi mengunyah cepat"], 0, "Kegagalan termoregulasi tubuh pada heatstroke mengancam kerusakan multiorgan fatal.");
addQ("pjo-k5-u20", 5, "Pertolongan Pertama pada Korban Pingsan (Syncope)", "sulit", "Saat upacara bendera ada murid yang pingsan karena dehidrasi dan kepanasan. Tindakan pertama evakuasi yang benar adalah ...", ["Membawa korban ke tempat teduh berangin, membaringkan telentang, dan meninggikan posisi kaki sekitar 30 cm", "Mendudukkan korban di kursi tinggi", "Memberi makan nasi padang saat pingsan", "Menyiram seember air es ke wajah"], 0, "Posisi trendelenburg (kaki lebih tinggi dari kepala) memperlancar pasokan darah oksigen kembali ke otak.");
addQ("pjo-k5-u21", 5, "Peran Serat Makanan Mencegah Kanker Usus Besar", "sulit", "Diet tinggi serat dari sayur-sayuran dan buah-buahan segar mengikat zat racun karsinogenik di saluran pencernaan dan mempercepat pengeluarannya. Manfaat klinisnya adalah ...", ["Menurunkan risiko terjadinya kanker usus besar (kanker kolorektal)", "Menambah lemak tubuh", "Memperberat kerja usus", "Memicu radang lambung"], 0, "Serat mempercepat transit time feses dan memfermentasi asam lemak rantai pendek pelindung kolon.");
addQ("pjo-k5-u22", 5, "Dampak Konsumsi Garam Berlebih Terhadap Tekanan Darah", "sulit", "Kelebihan natrium dari konsumsi garam dapur berlebih menahan volume air di dalam pembuluh darah. Konsekuensi fisiologisnya adalah ...", ["Volume darah meningkat sehingga tekanan dinding arteri melonjak (hipertensi)", "Tekanan darah turun drastis", "Darah menjadi manis", "Garam mengikis lambung"], 0, "Retensi cairan oleh natrium meningkatkan preload jantung dan tahanan vaskular perifer.");
addQ("pjo-k5-u23", 5, "Penyakit Rabies Akibat Gigitan Hewan Liar", "sulit", "Penyakit anjing gila (rabies) ditularkan melalui air liur hewan yang terinfeksi (anjing, kera, kucing) lewat luka gigitan. Pertolongan pertama darurat sebelum dibawa ke rumah sakit adalah ...", ["Mencuci luka gigitan dengan air bersih mengalir dan sabun detergen selama 15 menit", "Menutup luka rapat dengan tanah", "Mengikat kencang luka hingga mati rasa", "Mengoleskan kecap manis"], 0, "Sabun detergen merusak lapisan lipid envelope virus rabies pada luka sebelum menembus saraf.");
addQ("pjo-k5-u24", 5, "Peran Pendidikan Jasmani Membentuk Kecerdasan Kinestetik", "sulit", "Kecerdasan kinestetik jasmani (bodily-kinesthetic intelligence) yang diasah melalui pembelajaran PJOK mencakup kemampuan ...", ["Mengontrol gerakan tubuh secara terampil, menjaga keseimbangan, dan mengekspresikan gerak motorik kompleks", "Menghafal rumus aljabar", "Menghitung nilai tukar valuta asing", "Mengecat dinding rumah"], 0, "Kecerdasan kinestetik mengintegrasikan sistem saraf proprioseptif dan koordinasi motorik tubuh.");
addQ("pjo-k5-u25", 5, "Penerapan Fair Play dalam Olahraga Pelajar", "sulit", "Pemain sepak bola yang sengaja menendang bola keluar lapangan saat melihat pemain lawan tergeletak kesakitan di lapangan mencerminkan nilai ...", ["Fair play, rasa kemanusiaan, dan sportivitas sejati di atas kemenangan pertandingan", "Kelemahan mental bertanding", "Ketidaktahuan aturan bermain", "Kesalahan teknis semata"], 0, "Fair play mengutamakan keselamatan dan respek kemanusiaan melebihi skor pertandingan.");
addQ("pjo-k5-u26", 5, "Bahaya Meminum Minuman Es Saat Tubuh Mengalami Heat Exhaustion", "sulit", "Meminum air es yang terlalu beku dalam jumlah besar saat tubuh sedang sangat panas terik dapat memicu ...", ["Kram lambung (spasme saluran pencernaan) dan penyempitan mendadak pembuluh darah", "Peningkatan stamina lari seketika", "Penurunan suhu tubuh yang ideal", "Otot tubuh membesar"], 0, "Suhu dingin ekstrem memicu vasokonstriksi mendadak pada mukosa lambung.");
addQ("pjo-k5-u27", 5, "Aturan Batas Waktu Serangan 24 Detik Bola Basket", "sulit", "Dalam pertandingan bola basket resmi, satu tim yang menguasai bola diberikan batas waktu maksimal untuk melakukan tembakan ke ring lawan selama ...", ["24 detik", "60 detik", "10 detik", "5 menit"], 0, "Aturan 24-second shot clock mendorong tempo permainan basket menjadi dinamis dan cepat.");
addQ("pjo-k5-u28", 5, "Peran Sinar Matahari Pagi dalam Mencegah Osteoporosis Dini", "sulit", "Sinar matahari pagi merangsang sintesis vitamin D3 di kulit yang sangat penting untuk membantu penyerapan mineral ... dari makanan ke dalam tulang.", ["Kalsium dan fosfor", "Zat besi", "Kalium murni", "Magnesium sulfat"], 0, "Vitamin D esensial memfasilitasi absorpsi kalsium di epitel usus menuju matriks tulang.");
addQ("pjo-k5-u29", 5, "Analisis Bahaya Minuman Berkafein Tinggi pada Kualitas Tidur", "sulit", "Mengonsumsi kopi atau minuman boba berkafein tinggi menjelang malam hari mengganggu tidur nyenyak karena kafein memblokir reseptor ... di otak.", ["Adenosin (zat pemicu rasa kantuk alami)", "Dopamin", "Adrenalin", "Melatonin"], 0, "Kafein adalah antagonis reseptor adenosin sehingga otak terus terjaga dan sulit tertidur.");
addQ("pjo-k5-u30", 5, "Tanggung Jawab Menjaga Lingkungan Olahraga Bebas Polusi", "sulit", "Masyarakat yang terbiasa bersepeda santai atau berjalan kaki menuju sekolah/kantor berkontribusi nyata pada kesehatan lingkungan berupa ...", ["Mengurangi emisi gas buang karbon knalpot kendaraan bermotor dan menyehatkan jantung", "Menghabiskan jalan raya", "Membuat jalan menjadi macet", "Mengurangi produksi oksigen"], 0, "Transportasi aktif tanpa emisi menurunkan polusi udara dan meningkatkan kebugaran komunal.");

