addQ("pjo-k6-m01", 6, "Senam Lantai Sikap Lilin", "mudah", "Sikap tidur telentang lalu mengangkat kedua kaki dan pinggul lurus tegak ke atas ditopang kedua tangan di pinggang dinamakan sikap ...", ["Lilin", "Kayang", "Kapal terbang", "Split"], 0, "Sikap lilin meluruskan kedua kaki tegak vertikal ke atas ditopang tangan.");
addQ("pjo-k6-m02", 6, "Senam Lantai Gerakan Kayang", "mudah", "Gerakan meregangkan tubuh dengan melengkungkan punggung ke atas ditopang oleh kedua telapak tangan dan kedua telapak kaki di matras dinamakan gerak ...", ["Kayang", "Sikap lilin", "Guling depan", "Push up"], 0, "Kayang membentuk busur melengkung melatih kelenturan tulang belakang.");
addQ("pjo-k6-m03", 6, "Guling Belakang Senam Lantai", "mudah", "Gerakan menggulingkan badan ke arah belakang melingkar di atas matras dinamakan ...", ["Guling belakang (back roll)", "Guling depan", "Meroda", "Lompat harimau"], 0, "Guling belakang menggelindingkan badan ke belakang dari tengkuk hingga mendarat.");
addQ("pjo-k6-m04", 6, "Renang Gaya Punggung", "mudah", "Gaya renang di mana posisi tubuh telentang menghadap ke atas langit sehingga wajah selalu berada di atas permukaan air adalah gaya ...", ["Punggung (backstroke)", "Dada", "Bebas", "Kupu-kupu"], 0, "Renang gaya punggung dilakukan dengan punggung menghadap ke air dan wajah menghadap ke atas.");
addQ("pjo-k6-m05", 6, "Kotak P3K di Sekolah", "mudah", "Kotak khusus di ruang UKS sekolah yang berisi obat-obatan dan perban untuk pertolongan darurat dinamakan kotak ...", ["P3K (Pertolongan Pertama pada Kecelakaan)", "Tabungan", "Surat", "Suara"], 0, "Kotak P3K menyediakan perlengkapan pertolongan medis pertama.");
addQ("pjo-k6-m06", 6, "Kasa Steril P3K", "mudah", "Kain putih bersih berpori yang digunakan untuk menutup luka berdarah agar tidak kemasukan kuman debu adalah ...", ["Kasa steril", "Kain perca", "Kertas tisu", "Kapas basah"], 0, "Kasa steril higienis membalut luka dan mencegah infeksi kotoran luar.");
addQ("pjo-k6-m07", 6, "Cairan Antiseptik Luka", "mudah", "Cairan berwarna cokelat kemerahan (seperti povidone iodine) yang dioleskan pada luka untuk membunuh kuman bakteri dinamakan ...", ["Antiseptik", "Minyak kayu putih", "Sabun colek", "Cuka"], 0, "Antiseptik povidone iodine membasmi patogen pada tepi luka terbuka.");
addQ("pjo-k6-m08", 6, "Pengertian Pubertas", "mudah", "Masa transisi perubahan fisik dan emosi seorang anak menuju kedewasaan akibat aktifnya hormon reproduksi dinamakan masa ...", ["Pubertas", "Balita", "Lansia", "Bayi"], 0, "Pubertas adalah fase kematangan biologis organ reproduksi.");
addQ("pjo-k6-m09", 6, "Tanda Primer Pubertas Anak Laki-Laki", "mudah", "Tanda biologis primer yang menandai bahwa organ reproduksi anak laki-laki telah matang memproduksi sperma adalah mengalami ...", ["Mimpi basah", "Menstruasi", "Pertumbuhan gigi susu", "Rambut memutih"], 0, "Mimpi basah menandakan testis aktif memproduksi sel sperma.");
addQ("pjo-k6-m10", 6, "Tanda Primer Pubertas Anak Perempuan", "mudah", "Tanda biologis primer yang menandai bahwa organ reproduksi anak perempuan telah matang melepaskan sel telur adalah mengalami ...", ["Menstruasi (haid)", "Mimpi basah", "Suara membesar berat", "Tumbuh jakun"], 0, "Menstruasi menandai ovulasi rutin ovum oleh ovarium.");

addQ("pjo-k6-s01", 6, "Tanda Sekunder Pubertas Laki-Laki", "sedang", "Perubahan fisik sekunder yang terjadi pada anak laki-laki saat memasuki masa pubertas antara lain ...", ["Tumbuh jakun di leher, suara membesar berat, dan pundak bertambah bidang", "Suara melengking tinggi", "Pinggul melebar", "Kulit menjadi keriput"], 0, "Hormon testosteron memicu jakun membesar, pita suara menebal, dan bahu melebar.");
addQ("pjo-k6-s02", 6, "Tanda Sekunder Pubertas Perempuan", "sedang", "Perubahan fisik sekunder yang terjadi pada anak perempuan saat pubertas antara lain ...", ["Pinggul membesar dan payudara mulai tumbuh berkembang", "Tumbuh jakun menonjol", "Suara berubah menjadi sangat berat", "Tumbuh kumis tebal"], 0, "Hormon estrogen memicu penumpukan lemak subkutan di pinggul dan payudara.");
addQ("pjo-k6-s03", 6, "Menjaga Kebersihan Saat Menstruasi", "sedang", "Saat mengalami menstruasi, siswi perempuan harus mengganti pembalut secara teratur setiap ...", ["3 sampai 4 jam sekali atau saat terasa penuh", "Dua hari sekali", "Seminggu sekali", "Satu kali saja sehari"], 0, "Mengganti pembalut berkala mencegah perkembangbiakan bakteri dan bau tidak sedap.");
addQ("pjo-k6-s04", 6, "Merawat Kebersihan Kulit Berjerawat Pubertas", "sedang", "Peningkatan hormon pubertas merangsang kelenjar minyak di wajah sehingga timbul jerawat. Cara merawat wajah yang benar adalah ...", ["Mencuci muka secara teratur dengan sabun pembersih lembut dan tidak memencet jerawat dengan tangan kotor", "Memencet jerawat sampai berdarah", "Mengoleskan minyak goreng ke wajah", "Tidak pernah mencuci muka"], 0, "Mencuci muka mengangkat sebum minyak berlebih dan memencet jerawat memicu infeksi jaringan parut.");
addQ("pjo-k6-s05", 6, "Prinsip Pertolongan Pertama RICE", "sedang", "Metode penanganan awal pada cedera terkilir (keseleo) atau memar sendi adalah RICE yang merupakan kepanjangan dari ...", ["Rest, Ice, Compression, Elevation", "Run, Ice, Cold, Energy", "Relax, Iron, Clean, Eat", "Rescue, Inhale, Care, Exit"], 0, "RICE: Istirahatkan (Rest), Kompres es (Ice), Balut tekan (Compression), dan Tinggikan (Elevation).");
addQ("pjo-k6-s06", 6, "Fungsi Kompres Es (Ice) pada RICE", "sedang", "Tujuan mengompres bagian tubuh yang terkilir dengan es dingin selama 15-20 menit pada metode RICE adalah untuk ...", ["Mempersempit pembuluh darah (vasokonstriksi) guna mengurangi pendarahan dalam, bengkak, dan nyeri", "Memanaskan otot yang kram", "Mencairkan darah agar mengalir deras", "Membuat kulit membeku"], 0, "Suhu dingin memperlambat metabolisme selular dan meredakan peradangan.");
addQ("pjo-k6-s07", 6, "Fungsi Balut Tekan (Compression) pada RICE", "sedang", "Membalut sendi yang cedera menggunakan perban elastis (tensocrepe) dengan tekanan pas bertujuan untuk ...", ["Membatasi pergerakan sendi dan mencegah pembengkakan bertambah parah", "Menghentikan seluruh aliran darah hingga jari mati rasa", "Membuat kaki kaku selamanya", "Sebagai hiasan perban"], 0, "Kompresi elastis mengendalikan akumulasi eksudat cairan inflamasi pada sendi.");
addQ("pjo-k6-s08", 6, "Fungsi Meninggikan Posisi (Elevation) pada RICE", "sedang", "Meninggikan tungkai kaki yang terkilir lebih tinggi dari posisi jantung saat berbaring bertujuan untuk ...", ["Membantu aliran cairan darah balik ke jantung sehingga meredakan pembengkakan", "Membuat kaki terasa berat", "Menghentikan denyut jantung", "Membuat tidur tidak nyaman"], 0, "Elevasi memanfaatkan gravitasi mengurangi tekanan hidrostatik kapiler di area cedera.");
addQ("pjo-k6-s09", 6, "Lompat Kangkang di Atas Peti Lompat", "sedang", "Gerakan melompati peti lompat senam ketangkasan dengan kedua tungkai kaki dibuka lebar ke samping kiri dan kanan dinamakan ...", ["Lompat kangkang", "Lompat jongkok", "Lompat harimau", "Lompat tinggi"], 0, "Lompat kangkang menuntut abduksi kedua kaki saat melayang melewati peti.");
addQ("pjo-k6-s10", 6, "Lompat Jongkok di Atas Peti Lompat", "sedang", "Gerakan melompati peti lompat dengan kedua lutut ditarik ditekuk merapat ke dada di antara kedua lengan tangan dinamakan ...", ["Lompat jongkok", "Lompat kangkang", "Guling lenting", "Meroda"], 0, "Lompat jongkok melipat kedua kaki rapat di antara kedua tangan tumpuan.");
addQ("pjo-k6-s11", 6, "Gerakan Meroda (Cartwheel) Senam Ketangkasan", "sedang", "Gerakan memutar badan ke samping dengan tumpuan kedua tangan dan kedua kaki berputar menyerupai roda berputar dinamakan gerak ...", ["Meroda (radschlag / cartwheel)", "Kayang", "Sikap lilin", "Headstand"], 0, "Meroda bertumpu secara bergantian pada tangan dan kaki dalam bidang frontal putaran roda.");
addQ("pjo-k6-s12", 6, "Renang Gaya Punggung Posisi Bernapas", "sedang", "Keuntungan utama renang gaya punggung dibandingkan gaya lainnya adalah perenang lebih mudah mengambil napas karena ...", ["Posisi hidung dan mulut selalu berada di atas permukaan air", "Perenang tidak perlu bernapas", "Air kolam masuk ke hidung", "Bernapas lewat telinga"], 0, "Orientasi telentang menjaga saluran napas bebas di atas air sepanjang lintasan.");
addQ("pjo-k6-s13", 6, "Ayunan Lengan Renang Gaya Punggung", "sedang", "Pada renang gaya punggung, kedua lengan mengayun memutar ke belakang air secara bergantian. Fase tarikan lengan di dalam air menyapu menuju ke arah ...", ["Paha kaki untuk mendorong tubuh meluncur ke depan", "Atas kepala", "Luar kolam", "Dada"], 0, "Tarikan kayuhan (pull and push) berakhir dengan dorongan kuat ke arah paha.");
addQ("pjo-k6-s14", 6, "Gerakan Kaki Renang Gaya Punggung", "sedang", "Gerakan kaki pada renang gaya punggung bersumber dari persendian pangkal paha yang digerakkan ...", ["Mencambuk ke atas dan ke bawah secara bergantian dan rileks", "Menendang melingkar seperti katak", "Diam lurus tanpa gerak", "Menekuk lutut 90 derajat"], 0, "Gerakan flutter kick gaya punggung mencambuk vertikal bersumber dari pangkal paha.");
addQ("pjo-k6-s15", 6, "Mengelola Emosi di Masa Pubertas", "sedang", "Perubahan hormon pada masa pubertas sering membuat emosi remaja menjadi naik turun (moody). Cara positif mengelola emosi tersebut adalah ...", ["Menyalurkan energi melalui olahraga, hobi kesenian, dan bercerita jujur kepada orang tua", "Memendam kemarahan sendirian", "Melampiaskan dengan merusak barang", "Memusuhi sahabat"], 0, "Aktivitas fisik dan komunikasi terbuka dengan orang tua menyeimbangkan emosi remaja.");
addQ("pjo-k6-s16", 6, "Memilih Teman Bergaul yang Sehat", "sedang", "Dalam pergaulan remaja, kita harus pandai memilih teman yang saling mendukung kebaikan dan menghindari teman yang mengajak ...", ["Melakukan perundungan, merokok, tawuran, atau mencoba obat terlarang", "Belajar kelompok bersama", "Berolahraga di sore hari", "Membaca di perpustakaan"], 0, "Pergaulan sehat membangun karakter dan melindungi masa depan anak.");
addQ("pjo-k6-s17", 6, "Bahaya Rokok Terhadap Sistem Pembuluh Darah", "sedang", "Zat kimia beracun dalam rokok menyebabkan penyempitan pembuluh darah arteri dan peningkatan denyut jantung yang memicu ...", ["Penyakit stroke dan serangan jantung koroner di usia muda", "Paru-paru menjadi sehat", "Tulang menjadi kuat", "Darah bertambah jernih"], 0, "Nikotin memicu vasokonstriksi pembuluh darah dan memicu hipertensi kronis.");
addQ("pjo-k6-s18", 6, "Manfaat Menjaga Kebugaran Mental Melalui Olahraga", "sedang", "Saat berolahraga teratur, otak memproduksi hormon endorfin dan serotonin yang berfungsi untuk ...", ["Memperbaiki suasana hati (mood), mengurangi stres pikiran, dan memicu rasa bahagia", "Membuat mudah marah", "Menghambat daya pikir", "Menyebabkan mimpi buruk"], 0, "Endorfin adalah analgesik alami tubuh yang memicu rasa rileks dan euforia sehat.");
addQ("pjo-k6-s19", 6, "Penanganan Luka Bakar Ringan (Tingkat I)", "sedang", "Pertolongan pertama pada luka bakar ringan akibat tersiram air panas atau tersentuh wajan panas adalah ...", ["Mengalirkan air bersih mengalir bersuhu ruang selama 10-15 menit pada luka", "Mengoleskan pasta gigi atau mentega tebal", "Menaburkan garam dapur", "Menempelkan es batu beku langsung"], 0, "Air mengalir suhu ruang menyerap panas jaringan tanpa merusak sel epidermis.");
addQ("pjo-k6-s20", 6, "Tindakan Bila Teman Mengalami Henti Napas", "sedang", "Jika korban kecelakaan air tidak bernapas dan tidak merespons, orang di sekitar harus segera meminta bantuan medis darurat (ambulans) dan melakukan resusitasi yaitu ...", ["Resusitasi Jantung Paru (RJP / CPR)", "Mendudukkan korban di kursi", "Menyelimuti dengan terpal plastik", "Meninggalkan korban sendirian"], 0, "CPR mengompresi dada mempertahankan perfusi sirkulasi darah ke otak saat henti jantung.");

addQ("pjo-k6-u01", 6, "Analisis Biomekanika Lompat Kangkang Peti", "sulit", "Pada saat melakukan lompat kangkang di atas peti lompat, tolakan kedua telapak tangan pada peti lompat harus dilakukan pada saat ...", ["Tubuh mencapai titik tertinggi layangan sebelum bahu melewati bagian tengah peti", "Kaki sudah menyentuh lantai matras", "Badan terjatuh ke peti", "Setelah mendarat"], 0, "Dorongan eksplosif tangan saat titik kulminasi layangan memberikan gaya angkat melompati rintangan.");
addQ("pjo-k6-u02", 6, "Penyebab Jatuh Gagal Mendarat pada Senam Ketangkasan", "sulit", "Kegagalan mendarat stabil (terjatuh ke depan atau ke belakang) setelah melompati peti lompat umumnya disebabkan oleh ...", ["Posisi titik berat badan tidak berada di tengah tumpuan kedua kaki dan lutut tidak mengeper saat menyentuh matras", "Matras terlalu empuk", "Kedua tangan direntangkan", "Mata melihat ke depan"], 0, "Kekakuan lutut dan pergeseran center of gravity memicu hilangnya keseimbangan pendaratan.");
addQ("pjo-k6-u03", 6, "Analisis Sikap Lilin Penopang Pinggul", "sulit", "Agar sikap lilin dapat bertahan tegak lurus sempurna dan stabil dalam waktu lama, posisi kedua siku tangan di matras harus ...", ["Rapat selebar badan menopang kuat bagian pinggang belakang dengan jari-jari tangan terbuka lebar", "Dibuka sangat lebar ke samping", "Dilipat di atas dada", "Dilepaskan ke lantai"], 0, "Kedua siku rapat membentuk tripod penopang kokoh bagi tulang panggul dan tungkai.");
addQ("pjo-k6-u04", 6, "Analisis Fleksibilitas Tulang Belakang pada Gerak Kayang", "sulit", "Gerakan kayang menuntut fleksibilitas tinggi pada persendian vertebra tulang belakang dan kekuatan daya dorong otot ...", ["Kuadrisep paha, gluteus, deltoid bahu, dan trisep lengan", "Jari telunjuk saja", "Tulang pelipis", "Rahang bawah"], 0, "Kayang memadukan ekstensi vertebra thoracolumbar dengan daya dorong simetris 4 titik ekstremitas.");
addQ("pjo-k6-u05", 6, "Analisis Fase Tangkapan Air Renang Gaya Punggung", "sulit", "Pada fase tarikan (pull) lengan renang gaya punggung, sudut tekukan siku yang paling efisien menghasilkan gaya dorong meluncur adalah sudut ...", ["Sekitar 90 derajat di samping dada", "180 derajat lurus kaku", "Nol derajat rapat tubuh", "45 derajat melengkung ke atas air"], 0, "Menekuk siku 90 derajat (deep catch) memposisikan telapak tangan tegak lurus mendorong massa air ke belakang.");
addQ("pjo-k6-u06", 6, "Biomekanika Rotasi Tubuh (Body Roll) Renang Gaya Punggung", "sulit", "Mengapa perenang gaya punggung harus memutar sumbu panjang tubuhnya (body roll) sekitar 45 derajat ke kanan dan ke kiri seirama kayuhan lengan?", ["Mempermudah jangkauan ayunan lengan dalam air dan mengurangi hambatan bahu di permukaan air", "Agar perenang berguling tenggelam", "Membuat perenang pusing", "Supaya bisa melihat dasar kolam"], 0, "Body roll memudahkan rotasi persendian bahu dan memotong hambatan hidrodinamis.");
addQ("pjo-k6-u07", 6, "Dampak Pembalutan Terlalu Kencang pada Cedera", "sulit", "Kesalahan saat membalut sendi yang cedera dengan perban elastis (compression) terlalu kencang dapat berakibat fatal yaitu ...", ["Iskemia jaringan (aliran darah arteri terputus, ujung jari membiru dingin, dan kematian jaringan)", "Luka sembuh seketika", "Sendi bertambah lentur", "Pendarahan semakin deras"], 0, "Kompresi berlebih menyumbat sirkulasi perifer yang memicu nekrosis selular.");
addQ("pjo-k6-u08", 6, "Bahaya Penggunaan Odol / Minyak pada Luka Bakar", "sulit", "Mengoleskan pasta gigi (odol), mentega, atau kecap pada luka bakar sangat dilarang oleh dokter karena zat tersebut ...", ["Memerangkap panas di dalam jaringan kulit, memicu infeksi bakteri berat, dan memperparah kerusakan sel", "Mendinginkan luka secara alami", "Membuat kulit cepat sembuh", "Mencegah peradangan"], 0, "Zat pekat memerangkap energi kalor di dermis kulit dan mengkontaminasi luka steril.");
addQ("pjo-k6-u09", 6, "Analisis Kebutuhan Nutrisi Zat Besi Saat Pubertas Perempuan", "sulit", "Siswi perempuan yang memasuki masa pubertas dan mengalami menstruasi rutin dianjurkan mengonsumsi tablet tambah darah (zat besi) dan makanan kaya zat besi untuk mencegah ...", ["Anemia defisiensi besi (mudah lelah, 5L: lesu, lelah, letih, lemah, lalai)", "Kelebihan sel darah merah", "Penyakit diabetes", "Kenaikan berat badan"], 0, "Kehilangan darah bulanan menurunkan feritin darah yang memicu anemia mikrositik.");
addQ("pjo-k6-u10", 6, "Fisiologi Pengaruh Hormon Testosteron pada Remaja Laki-Laki", "sulit", "Hormon testosteron yang diproduksi oleh testis saat pubertas anak laki-laki merangsang perkembangan fisiologis berupa ...", ["Pertumbuhan massa otot rangka yang pesat, penambahan tinggi tulang panjang, dan pendalaman pita suara", "Penumpukan lemak di pinggul", "Pelebaran rongga panggul", "Penipisan tulang rusuk"], 0, "Testosteron adalah hormon anabolik androgenik alami pembentuk hipertrofi otot dan maskulinitas.");
addQ("pjo-k6-u11", 6, "Manajemen Emosi Melalui Aktivitas Fisik Aerobik", "sulit", "Ketika remaja merasakan kemarahan atau kegelisahan yang memuncak, berolahraga lari lintas alam atau bermain basket membantu meredakan ketegangan mental karena ...", ["Menurunkan kadar hormon stres kortisol dan memicu pelepasan neurotransmiter penenang endorfin", "Menaikkan tekanan darah hingga pingsan", "Menghilangkan seluruh ingatan memori", "Membuat badan lumpuh lemas"], 0, "Aktivitas aerobik memodulasi poros HPA (hypothalamic-pituitary-adrenal) penurun kortisol.");
addQ("pjo-k6-u12", 6, "Pencegahan Terjadinya Pelecehan Seksual di Media Sosial", "sulit", "Dalam pergaulan digital, sikap bijak seorang remaja untuk melindungi privasi kehormatan diri adalah ...", ["Tidak membagikan foto pribadi tanpa busana/terbuka kepada siapa pun dan segera memblokir akun yang meminta hal tak pantas", "Mengirimkan foto pribadi kepada orang asing di internet", "Menuruti semua ancaman di dunia maya", "Memberikan kata sandi akun kepada teman baru"], 0, "Menjaga batas privasi digital melindungi anak dari kejahatan siber dan eksploitasi seksual.");
addQ("pjo-k6-u13", 6, "Prinsip Pertolongan Korban Tenggelam 'Reach, Throw, Row, Go'", "sulit", "Jika melihat orang tenggelam di danau dalam, urutan prinsip penyelamatan diri yang paling aman bagi penolong amatir adalah ...", ["Mencoba meraih dengan galah/bambu (Reach) atau melempar pelampung bertali (Throw) tanpa langsung nekat menceburkan diri", "Langsung melompat ke air memeluk korban yang panik", "Menyelam ke bawah korban", "Menunggu hingga korban tenggelam ke dasar"], 0, "Korban tenggelam yang panik berisiko menenggelamkan penolong tanpa alat bantu apung.");
addQ("pjo-k6-u14", 6, "Penanganan Pertama Terkilir Sendi Pergelangan Kaki (Sprain Ankle)", "sulit", "Segera setelah pergelangan kaki terkilir di lapangan, tindakan yang HARUS DIHINDARI selama 48 jam pertama (aturan No HARM) adalah ...", ["Heat (panas), Alcohol, Running (olahraga lari), dan Massage (pijat urut paksa pada cedera)", "Mengompres dengan es dingin", "Mengistirahatkan kaki", "Meninggikan posisi kaki saat tidur"], 0, "HARM (Heat, Alcohol, Running, Massage) memperparah pendarahan dan inflamasi cedera akut.");
addQ("pjo-k6-u15", 6, "Analisis Kebutuhan Kebugaran Kardiovaskular VO2Max", "sulit", "Nilai VO2max seorang atlet mencerminkan kapasitas maksimal tubuh dalam ...", ["Menghirup, mengangkut, dan menggunakan oksigen saat melakukan kerja fisik intensitas tinggi", "Menahan beban besi seberat-beratnya", "Menyimpan cadangan lemak tubuh", "Mengeluarkan keringat sebanyak-banyaknya"], 0, "VO2max adalah indikator baku kebugaran aerobik daya tahan kardiorespirasi.");
addQ("pjo-k6-u16", 6, "Pola Makan Atlet Menjelang Pertandingan (Carbo-Loading)", "sulit", "Strategi atlet lari maraton mengonsumsi makanan tinggi karbohidrat kompleks 2-3 hari sebelum lomba bertujuan untuk ...", ["Memaksimalkan simpanan glikogen di dalam otot dan hati sebagai bahan bakar cadangan energi jarak jauh", "Menambah tumpukan lemak jahat", "Membuat tubuh menjadi berat kaku", "Mengurangi asupan air tubuh"], 0, "Superkompensasi glikogen menunda kelelahan otot (hitting the wall) saat lomba daya tahan.");
addQ("pjo-k6-u17", 6, "Pengaruh Merokok Terhadap Elastisitas Dinding Pembuluh Darah", "sulit", "Racun nikotin dan radikal bebas asap rokok merusak lapisan endotelium pembuluh darah sehingga memicu proses aterosklerosis yang ditandai dengan ...", ["Pengerasan dan penyempitan lumen pembuluh darah sehingga tekanan darah meningkat drastis", "Pembuluh darah menjadi sangat lentur dan elastis", "Darah mengalir semakin lancar tanpa hambatan", "Jumlah sel darah putih berkurang habis"], 0, "Disfungsi endotelial mempercepat pembentukan plak ateroma penyumbat sirkulasi.");
addQ("pjo-k6-u18", 6, "Analisis Bahaya Alkohol Terhadap Sistem Koordinasi Serebelum", "sulit", "Otak kecil (serebelum) bertugas mengatur keseimbangan tubuh dan koordinasi gerak halus. Seseorang yang mabuk alkohol berjalan sempoyongan dan bicaranya cadel karena ...", ["Alkohol menekan fungsi kontrol neuromuskular pada jaringan serebelum otak kecil", "Otot kaki memanjang secara mendadak", "Alkohol membakar tulang paha", "Mata kehilangan bola mata"], 0, "Intoksikasi etanol melumpuhkan transmisi sinaptik GABAergik di serebelum.");
addQ("pjo-k6-u19", 6, "Pentingnya Menjaga Kebersihan Organ Reproduksi Eksternal", "sulit", "Menjaga kebersihan lipatan paha dan organ reproduksi dengan mengeringkannya menggunakan handuk bersih lembut setelah mandi bertujuan untuk mencegah ...", ["Tumbuhnya jamur Candida albicans yang memicu keputihan patologis dan rasa gatal perih", "Pertumbuhan rambut rontok", "Penyakit patah tulang pinggul", "Kekurangan vitamin A"], 0, "Kelembapan maserasi memicu vaginitis dan balanitis fungal.");
addQ("pjo-k6-u20", 6, "Sikap Menghargai Perubahan Fisik Teman Sebaya di Masa Pubertas", "sulit", "Di kelas 6 ada teman yang bertubuh jauh lebih tinggi atau suaranya sudah membesar sementara yang lain belum. Sikap yang beradab dan terdidik adalah ...", ["Memahami bahwa waktu pubertas setiap orang berbeda-beda dan saling menghormati tanpa mengejek", "Menertawakan teman yang belum puber", "Menjuluki teman dengan panggilan fisik yang merendahkan (body shaming)", "Mengucilkan teman yang suaranya membesar"], 0, "Variasi onset pubertas dipengaruhi genetik, gizi, dan lingkungan.");
addQ("pjo-k6-u21", 6, "Analisis Bahaya Minuman Beralkohol Terhadap Lambung", "sulit", "Mengonsumsi alkohol secara berulang merusak lapisan mukosa lambung yang memicu pendarahan lambung yang dikenal sebagai penyakit ...", ["Gastritis erosif / tukak lambung akut", "Radang amandel tonsil", "Kutu air", "Miopi"], 0, "Etanol mengikis pelindung mukosa asam lambung dan memicu perdarahan hematemesis.");
addQ("pjo-k6-u22", 6, "Tindakan Bila Digigit Ular Berbisa di Alam Terbuka", "sulit", "Penanganan darurat medis modern yang benar pada korban gigitan ular berbisa adalah ...", ["Melakukan imobilisasi total pada anggota tubuh yang tergigit (jangan digerakkan/dipasang bidai) dan segera bawa ke RS untuk serum antibisa (SABU)", "Menyayat luka dengan pisau dan menyedot darah dengan mulut", "Mengikat kencang dengan tali hingga darah tidak mengalir sama sekali", "Mengoleskan minyak tanah mendidih"], 0, "Imobilisasi membatasi penyebaran racun bisa ular melalui saluran limfatik pembuluh getah bening.");
addQ("pjo-k6-u23", 6, "Bahaya Perundungan Fisik dan Verbal (Bullying) di Sekolah", "sulit", "Tindakan perundungan (bullying) baik ejekan verbal maupun kekerasan fisik di sekolah dapat merusak masa depan korban karena memicu ...", ["Trauma psikologis mendalam, depresi, kecemasan sosial, hingga penurunan prestasi belajar drastis", "Kenaikan nilai rapor", "Tubuh korban bertambah kuat kekar", "Kecerdasan emosional meningkat"], 0, "Bullying menimbulkan luka emosional jangka panjang dan menurunkan harga diri korban.");
addQ("pjo-k6-u24", 6, "Kebugaran Jasmani Daya Ledak Otot (Power)", "sulit", "Daya ledak otot (power) merupakan perpaduan harmonis antara dua komponen kebugaran jasmani yaitu ...", ["Kekuatan (strength) dan kecepatan (speed) dalam waktu yang sangat singkat", "Kelenturan dan daya tahan kardio", "Keseimbangan dan ketepatan", "Kelincahan dan koordinasi lambat"], 0, "Power = Force x Velocity (kemampuan mengerahkan kekuatan maksimal secepat mungkin).");
addQ("pjo-k6-u25", 6, "Pengaruh Kebugaran Jasmani Terhadap Kesehatan Tulang Lansia", "sulit", "Membiasakan diri aktif berolahraga dengan beban tubuh (weight-bearing exercise) seperti jalan cepat dan lompat sejak usia SD bermanfaat jangka panjang mencegah ...", ["Osteoporosis (pengeroposan tulang) di usia senja kelak", "Penyakit kencing manis", "Radang usus buntu", "Infeksi saluran kemih"], 0, "Beban mekanis merangsang osteoblas menimbun matriks kalsium tulang puncak (peak bone mass).");
addQ("pjo-k6-u26", 6, "Adab Menghadapi Lawan yang Mengalami Cedera Saat Bertanding", "sulit", "Ketika dalam sebuah pertandingan sepak bola atau basket pemain lawan mengalami benturan keras dan terkapar cedera, sikap ksatria yang benar adalah ...", ["Segera menghentikan permainan dan membantu memanggil tim medis wasit untuk menolong lawan", "Terus menggiring bola dan mencetak gol tanpa peduli", "Menertawakan lawan yang kesakitan", "Menginjak kaki lawan yang cedera"], 0, "Menjunjung tinggi nilai kemanusiaan dan sportivitas di atas ambisi kemenangan sesaat.");
addQ("pjo-k6-u27", 6, "Penanganan Pertama Anak Tersedak Benda Padat Mainan", "sulit", "Jika seorang anak tersedak kelereng hingga tidak bisa bersuara, batuk, atau bernapas, manuver darurat yang harus dilakukan segera adalah ...", ["Manuver Heimlich (abdominal thrusts) dengan merangkul dari belakang dan menghentak ulu hati ke arah dalam atas", "Memberi minum segelas air es", "Menyuruh anak berlari keliling ruangan", "Memasukkan jari ke dalam tenggorokan secara membabi buta"], 0, "Hentakan diafragma mendesak udara paru-paru melontarkan benda asing keluar dari saluran napas.");
addQ("pjo-k6-u28", 6, "Pentingnya Pola Hidup Seimbang di Era Serba Digital", "sulit", "Strategi cerdas membatasi screen time (waktu di depan layar gawai) bagi murid kelas 6 adalah menerapkan aturan 20-20-20 yaitu ...", ["Setiap 20 menit menatap layar, istirahatkan mata selama 20 detik dengan melihat objek berjarak 20 kaki (6 meter)", "Menatap layar 20 jam non-stop", "Bermain game selama 20 hari", "Tidur selama 20 menit di depan layar"], 0, "Rule 20-20-20 merelaksasi otot siliaris lensa mata dari kelelahan visual digital.");
addQ("pjo-k6-u29", 6, "Menolak Tawaran Merokok dari Teman Sebaya", "sulit", "Tekanan teman sebaya (peer pressure) sering mengajak anak mencoba merokok agar diakui dalam kelompok pergaulan. Respon asertif yang paling tepat adalah ...", ["Menolak dengan sopan namun tegas: 'Maaf, saya tidak merokok demi menjaga kesehatan dan kebugaran tubuh saya'", "Menerima rokok lalu menyembunyikannya di saku", "Takut dijauhi sehingga ikut merokok", "Membalas dengan memukul teman"], 0, "Komunikasi asertif mempertahankan prinsip kesehatan pribadi secara percaya diri tanpa kekerasan.");
addQ("pjo-k6-u30", 6, "Filosofi 'Men Sana in Corpore Sano'", "sulit", "Pepatah kuno bangsa Romawi 'Men Sana in Corpore Sano' memiliki makna filosofis mendalam yang menjadi semboyan olahraga yaitu ...", ["Di dalam tubuh yang sehat terdapat jiwa yang kuat dan pikiran yang jernih", "Tubuh yang kuat tidak membutuhkan ilmu pengetahuan", "Hanya orang kaya yang boleh berolahraga", "Kesehatan jasmani tidak ada hubungannya dengan pikiran"], 0, "Keseimbangan harmonis antara kesehatan fisik (jasmani) dan ketenangan batin (rohani).");

